"use strict";(self.webpackChunkpy_tfhe_oss_doc=self.webpackChunkpy_tfhe_oss_doc||[]).push([[8071],{1305:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","label":"Athena Intro","href":"/athena/docs/intro","docId":"intro","unlisted":false},{"type":"category","label":"Submodules","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Generating Embeddings","href":"/athena/docs/submodules/Embedding","docId":"submodules/Embedding","unlisted":false},{"type":"link","label":"Database Interface","href":"/athena/docs/submodules/database","docId":"submodules/database","unlisted":false},{"type":"link","label":"Milvus Vector Database","href":"/athena/docs/submodules/Milvus","docId":"submodules/Milvus","unlisted":false},{"type":"link","label":"PostgreSQL and pgvector","href":"/athena/docs/submodules/Postgres","docId":"submodules/Postgres","unlisted":false},{"type":"link","label":"Large Language Models","href":"/athena/docs/submodules/LLM","docId":"submodules/LLM","unlisted":false},{"type":"link","label":"Profiling","href":"/athena/docs/submodules/Profiling","docId":"submodules/Profiling","unlisted":false},{"type":"link","label":"Configuration Reference","href":"/athena/docs/submodules/Configuration","docId":"submodules/Configuration","unlisted":false}],"href":"/athena/docs/category/submodules"}]},"docs":{"intro":{"id":"intro","title":"Athena Intro","description":"Athena is an end-to-end framework for Retrieval-Augmented Generation (RAG) applications. It allows users to build flexible RAG systems and provides system design guidelines through different kinds of metrics. This is the open-source version, optimized for clarity and usability. It is organized into multiple submodules that hide the complexity of the backends (vector database, LLM, etc) and enable flexible builds for RAG systems for different purposes.","sidebar":"tutorialSidebar"},"submodules/Configuration":{"id":"submodules/Configuration","title":"Configuration Reference","description":"The pipeline is driven by a single config.yaml file. Pass it to the orchestration script with:","sidebar":"tutorialSidebar"},"submodules/database":{"id":"submodules/database","title":"Database Interface","description":"Athena provides two database interface classes with unified APIs: MilvusInterface and PostgresInterface. This design allows RAG pipelines to swap between vector databases without changing orchestration code.","sidebar":"tutorialSidebar"},"submodules/Embedding":{"id":"submodules/Embedding","title":"Generating Embeddings","description":"For offline embedding generation with high batch sizes, use the offline generation script provided in the emb/ directory.","sidebar":"tutorialSidebar"},"submodules/LLM":{"id":"submodules/LLM","title":"Large Language Models","description":"Athena provides interfaces for vLLM for server-grade or performance-sensitive workloads and Ollama for simple LLM hosting on personal desktops.","sidebar":"tutorialSidebar"},"submodules/Milvus":{"id":"submodules/Milvus","title":"Milvus Vector Database","description":"This page covers Milvus environment setup and important characteristics for working with the Milvus database.","sidebar":"tutorialSidebar"},"submodules/Postgres":{"id":"submodules/Postgres","title":"PostgreSQL and pgvector","description":"Unlike Milvus, PostgreSQL is a row-oriented traditional relational database. pgvector is a lightweight vector search extension built for PostgreSQL. To install PostgreSQL with pgvector enabled, see the official pgvector installation guide.","sidebar":"tutorialSidebar"},"submodules/Profiling":{"id":"submodules/Profiling","title":"Profiling","description":"RAG-Specific Metrics","sidebar":"tutorialSidebar"}}}}')}}]);